import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Reclaim CephFS Capacity Through Pool Tiering + Migration","description":"","frontmatter":{"title":"Reclaim CephFS Capacity Through Pool Tiering + Migration","date":"2026-06-25T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["CephFS","Erasure Coding","存储优化","性能优化","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Reclaim_CephFS_Capacity_Through_Pool_Tiering_+_Migration.md","filePath":"posts/2026/Reclaim_CephFS_Capacity_Through_Pool_Tiering_+_Migration.md","lastUpdated":null}'),i={name:"posts/2026/Reclaim_CephFS_Capacity_Through_Pool_Tiering_+_Migration.md"};function l(n,t,s,h,d,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="reclaim-cephfs-capacity-through-pool-tiering-migration" tabindex="-1">Reclaim CephFS Capacity Through Pool Tiering + Migration <a class="header-anchor" href="#reclaim-cephfs-capacity-through-pool-tiering-migration" aria-label="Permalink to &quot;Reclaim CephFS Capacity Through Pool Tiering + Migration&quot;">​</a></h1><h2 id="演讲者介绍" tabindex="-1">演讲者介绍 <a class="header-anchor" href="#演讲者介绍" aria-label="Permalink to &quot;演讲者介绍&quot;">​</a></h2><p>本次演讲者是 Ceph 项目的 SEF Ambassador（社区大使）兼文档负责人，自 2014 年起运营 Ceph 集群，2017 年后实现稳定运行。他同时也是 QLC SSD 的积极倡导者，并著有一本关于 Ceph 的书籍（虽然他自嘲已经&quot;越来越旧&quot;了）。</p><h2 id="背景-存储成本飙升的困境" tabindex="-1">背景：存储成本飙升的困境 <a class="header-anchor" href="#背景-存储成本飙升的困境" aria-label="Permalink to &quot;背景：存储成本飙升的困境&quot;">​</a></h2><p>演讲者以一句经典观察开篇：<strong>数据会不断膨胀以填满可用存储，甚至超出可用存储</strong>。这一规律从早期的 Fuji Eagles 380MB 硬盘时代到今天依然成立。</p><p>当前存储市场面临的严峻现实：</p><ul><li>企业、教育机构等用户的存储需求从 <strong>数百 TB</strong> 迅速增长到 <strong>PB 级别</strong></li><li>内存和存储市场（包括 SSD、DRAM、传统 HDD）经历了<strong>剧烈的价格上涨</strong></li><li>从下单到发货，价格涨幅高达 <strong>400%</strong></li><li>演讲者举例：2023 年一块 7.6TB P-5520 SSD 售价 700 美元，如今已涨到约 5000 美元</li></ul><p>在这样的成本压力下，如何在满足用户存储需求的同时让采购预算通过 CFO 的审批？答案之一就是<strong>提升存储效率</strong>。</p><h2 id="cephfs-与-erasure-coding-的结合" tabindex="-1">CephFS 与 Erasure Coding 的结合 <a class="header-anchor" href="#cephfs-与-erasure-coding-的结合" aria-label="Permalink to &quot;CephFS 与 Erasure Coding 的结合&quot;">​</a></h2><h3 id="传统部署方式的问题" tabindex="-1">传统部署方式的问题 <a class="header-anchor" href="#传统部署方式的问题" aria-label="Permalink to &quot;传统部署方式的问题&quot;">​</a></h3><p>CephFS 作为流行的、高可用的 POSIX 风格分布式文件系统，部署初期通常使用默认的<strong>三副本（replica-3）存储池</strong>来满足性能需求。但随着集群规模增长，采购预算中的零越来越多，迫切需要从 replication 切换到 <strong>Erasure Coding (EC)</strong> 来更高效地利用原始容量。</p><h3 id="erasure-coding-的空间效率" tabindex="-1">Erasure Coding 的空间效率 <a class="header-anchor" href="#erasure-coding-的空间效率" aria-label="Permalink to &quot;Erasure Coding 的空间效率&quot;">​</a></h3><p>不同的 EC profile 提供不同的空间放大系数（space amplification factor）：</p><table tabindex="0"><thead><tr><th>存储策略</th><th>空间放大系数</th><th>说明</th></tr></thead><tbody><tr><td>Replica-3</td><td>3x</td><td>三副本，空间占用最大</td></tr><tr><td>EC 4+2</td><td>1.5x</td><td>可用空间翻倍</td></tr><tr><td>EC 6+3</td><td>1.5x</td><td>同样的空间效率，更高容错</td></tr></tbody></table><h3 id="ec-的传统限制与突破" tabindex="-1">EC 的传统限制与突破 <a class="header-anchor" href="#ec-的传统限制与突破" aria-label="Permalink to &quot;EC 的传统限制与突破&quot;">​</a></h3><p>传统观点认为 EC 只适合写入性能要求不高的工作负载，因为 EC 需要写入更多驱动器，尤其在 HDD 上 IOPS 有限时容易饱和。但随着 <strong>NVMe SSD</strong> 的普及和 <strong>Tentacle 版本中 fast EC 的优化工作</strong>（由 IBM 团队贡献），EC 的性能已经大幅接近 replication 的水平。</p><p>演讲者特别指出，HDD 往往是<strong>虚假经济</strong>——需要综合考虑 IOPS/美元、IOPS/TB、IOPS/机架单元、PB/机架单元以及恢复时间等多个维度。目前市场上已有多款 245TB SSD，在更小的体积内提供远超 HDD 的容量。</p><h2 id="cephfs-的多数据池与-file-layout-特性" tabindex="-1">CephFS 的多数据池与 File Layout 特性 <a class="header-anchor" href="#cephfs-的多数据池与-file-layout-特性" aria-label="Permalink to &quot;CephFS 的多数据池与 File Layout 特性&quot;">​</a></h2><h3 id="关键机制-多个数据池" tabindex="-1">关键机制：多个数据池 <a class="header-anchor" href="#关键机制-多个数据池" aria-label="Permalink to &quot;关键机制：多个数据池&quot;">​</a></h3><p>很多人不知道的是，CephFS volume 除了必须的 <strong>metadata pool</strong>（通常命名为 <code>*_meta</code>）之外，可以拥有<strong>多个数据池（data pool）</strong>，并且这些池可以使用完全不同的存储介质和数据保护策略。</p><h3 id="file-layout-文件布局" tabindex="-1">File Layout（文件布局） <a class="header-anchor" href="#file-layout-文件布局" aria-label="Permalink to &quot;File Layout（文件布局）&quot;">​</a></h3><p>CephFS 有一个鲜为人知的特性——<strong>file layout / directory layout</strong>。通过 <code>setfattr</code> 命令可以在文件或目录上设置该属性：</p><ul><li>设置在目录上时，其下所有新文件和子目录都会继承该布局</li><li>file layout 可以指定将新写入的文件存放到<strong>非默认的数据池</strong>上</li><li>这意味着可以将新数据路由到使用 EC 的、基于更经济存储介质的池中</li></ul><h2 id="核心方案-逐文件迁移策略" tabindex="-1">核心方案：逐文件迁移策略 <a class="header-anchor" href="#核心方案-逐文件迁移策略" aria-label="Permalink to &quot;核心方案：逐文件迁移策略&quot;">​</a></h2><h3 id="问题的由来" tabindex="-1">问题的由来 <a class="header-anchor" href="#问题的由来" aria-label="Permalink to &quot;问题的由来&quot;">​</a></h3><p>演讲者提到了一位社区成员的案例：该用户拥有 PB 级别的全 NVMe SSD 集群，使用 replica-3 池，存储成本极高。扩容报价比预算高出了一个数量级。但其工作负载<strong>约 90% 为读取</strong>，写入压力较小，这为切换到 EC 提供了理想条件。</p><h3 id="迁移脚本的工作原理" tabindex="-1">迁移脚本的工作原理 <a class="header-anchor" href="#迁移脚本的工作原理" aria-label="Permalink to &quot;迁移脚本的工作原理&quot;">​</a></h3><p>演讲者受到 Reddit 用户 Maran42 发布的 transcoder 脚本启发，开发了改进版本。其核心工作流程：</p><ol><li><strong>逐文件遍历</strong> CephFS volume 或子目录</li><li>为每个文件创建一个使用新 file layout 的副本（例如从 replica-3 转为 EC 6+3）</li><li>通过**原子重命名（atomic rename）**替换原文件</li><li>包含多种安全保护机制，避免损坏正在写入的文件</li></ol><h3 id="逐文件迁移的优势" tabindex="-1">逐文件迁移的优势 <a class="header-anchor" href="#逐文件迁移的优势" aria-label="Permalink to &quot;逐文件迁移的优势&quot;">​</a></h3><p>与传统的整池迁移方案相比，逐文件迁移具有显著优势：</p><ul><li><strong>无需大量临时空间</strong>：传统方案需要翻倍空间来先创建所有数据的新副本，而逐文件方式逐个处理，空间开销极小</li><li><strong>渐进式迁移</strong>：可以随时中断和恢复，脚本是<strong>幂等的（idempotent）</strong></li><li><strong>灵活的迁移策略</strong>：可以分阶段进行——先处理大文件、后处理小文件；先处理旧文件、后处理新文件</li><li><strong>自动设置新布局</strong>：脚本会将顶层目录的 file layout 设置为指向 EC 池，确保后续新文件自动写入 EC 池</li></ul><h3 id="迁移参数配置" tabindex="-1">迁移参数配置 <a class="header-anchor" href="#迁移参数配置" aria-label="Permalink to &quot;迁移参数配置&quot;">​</a></h3><p>实际部署中的典型配置：</p><table tabindex="0"><thead><tr><th>参数</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>并行线程数</td><td>15</td><td>同时处理 15 个文件</td></tr><tr><td>最小文件大小</td><td>500KB</td><td>避免小文件的 EC 空间放大问题</td></tr><tr><td>文件年龄</td><td>&gt;1天</td><td>避免处理正在频繁变更的文件</td></tr><tr><td>多硬链接文件</td><td>跳过</td><td>出于安全考虑</td></tr><tr><td>EC profile</td><td>6+3</td><td>因为使用了可靠性较差的退役 SSD（如 Samsung NF1）</td></tr></tbody></table><p>单个客户端系统的处理速度约为 <strong>12-15 TB/小时</strong>。</p><h3 id="小文件的空间放大问题" tabindex="-1">小文件的空间放大问题 <a class="header-anchor" href="#小文件的空间放大问题" aria-label="Permalink to &quot;小文件的空间放大问题&quot;">​</a></h3><p>在 Tentacle 版本之前，EC 对小文件存在严重的空间放大问题：即使只有 1 字节的对象，在 8+3 EC 下也会写入 11 倍的最小分配单元。因此迁移脚本会跳过小于 500KB 的文件。</p><p>Tentacle 版本的 fast EC 优化大幅降低了这一阈值，未来版本（可能是 Umbrella）有望进一步改善。演讲者引用了 Mark Nelson 的可视化电子表格来说明这一问题。</p><h2 id="实际效果" tabindex="-1">实际效果 <a class="header-anchor" href="#实际效果" aria-label="Permalink to &quot;实际效果&quot;">​</a></h2><p>通过将超过 500KB 且年龄超过 1 天的文件从 replication 迁移到 EC 6+3：</p><ul><li><strong>原始存储空间减少约 44%</strong>（理论上最优为 50%，但由于跳过多硬链接文件和小文件，实际略低）</li><li>对于 PB 级集群，这意味着<strong>节省约 200TB 的原始空间</strong></li><li>整个过程中，replica-3 池的空间下降速度<strong>快于</strong> EC 池的空间增长速度</li></ul><h2 id="crush-rule-与-ec-profile-管理" tabindex="-1">CRUSH Rule 与 EC Profile 管理 <a class="header-anchor" href="#crush-rule-与-ec-profile-管理" aria-label="Permalink to &quot;CRUSH Rule 与 EC Profile 管理&quot;">​</a></h2><p>脚本还自动管理 <strong>EC profiles</strong>、<strong>CRUSH rules</strong> 和 RADOS pools。一个重要细节：</p><ul><li>Ceph 集群存在 <strong>256 个 CRUSH rules 的硬性上限</strong></li><li>Rook 为每个池创建独立 rule 的做法容易触达这一上限</li><li>脚本通过<strong>复用 EC profiles 和 CRUSH rules</strong> 来避免此问题</li></ul><p>演讲者坦言尚未在 CephFS subvolumes 上测试该脚本，但预计不会有兼容性问题。脚本也支持反向迁移（从 EC 回到 replication），但尚未经过测试。</p><h2 id="关键总结" tabindex="-1">关键总结 <a class="header-anchor" href="#关键总结" aria-label="Permalink to &quot;关键总结&quot;">​</a></h2><ol><li><strong>CephFS 支持多数据池</strong>，不同池可以使用不同的存储介质和数据保护策略</li><li><strong>File layout</strong> 允许在目录或文件级别控制数据存放位置，新文件自动继承目录的布局设置</li><li><strong>逐文件迁移</strong>方案避免了传统整池迁移需要大量临时空间的问题</li><li>在 90% 读取的工作负载下，从 replication 切换到 EC 可以实现约 <strong>44% 的存储空间节省</strong></li><li>NVMe SSD + fast EC（Tentacle）的组合使得更多工作负载能够使用 EC 而不牺牲性能</li><li>脚本是幂等的、可中断恢复的，支持灵活的分阶段迁移策略</li></ol><p>相关脚本已发布在 Git 仓库中，欢迎社区贡献改进建议。</p>',49)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
